"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["77776"],{22358(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.campus.sigla_acentuacao_invalida","status":422,"titulo":"Sigla do campus cont\xe9m acentua\xe7\xe3o gr\xe1fica"},"descricao":{"codigo":"uniplus.configuracao.campus.sigla_acentuacao_invalida","requisitos":[],"oQueAconteceu":["A **sigla** informada cont\xe9m acentua\xe7\xe3o gr\xe1fica. A sigla do campus \xe9 um\\nidentificador institucional e \xe9 formada sem acento, para que duas siglas\\nvisualmente semelhantes n\xe3o coexistam.","A regra reconhece tanto o caractere acentuado pr\xe9-composto quanto a\\nrepresenta\xe7\xe3o formada por letra seguida de marca combinante \u2014 as duas\\nformas de escrever `C\xc1MAR` em Unicode s\xe3o recusadas."],"comoResolver":["Reenvie a sigla sem acentua\xe7\xe3o. A API n\xe3o remove o acento nem substitui o\\ncaractere: o valor informado \xe9 preservado para corre\xe7\xe3o, porque remov\xea-lo\\nalteraria o dado enviado e poderia colidir com a sigla de outro campus.","Letras sem acentua\xe7\xe3o, n\xfameros e h\xedfen continuam v\xe1lidos (`CMB`,\\n`CMRB-I`), e a convers\xe3o para mai\xfasculas segue acontecendo (`camar` \xe9\\ngravado como `CAMAR`)."],"ondeAparece":["Cria\xe7\xe3o de um campus","Atualiza\xe7\xe3o de um campus"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Campus"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);